import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ScopeBuffer } from '../../src/instruments/Scope.tsx';
import { decodeSigc, encodeSigc, SigcError } from '../../src/instruments/sigc.ts';

// Bytes generated by scripts/sigc.py (the CLI's existing Python codec).
const pythonHex = '';
const fromHex = (hex: string) => Uint8Array.from(hex.match(/../g)!.map((x) => parseInt(x, 16)));

function capture() {
  return { timesNs: [0, 10, 30], traces: [
    { name: 'ch1', fullScaleMv: 3300, samplesMv: Int16Array.from([0, 1000, -250]) },
    { name: 'ch2', fullScaleMv: 3300, samplesMv: Int16Array.from([3300, 2000, 0]) }
  ] };
}

test('browser SIGC bytes match the production Python encoder', () => {
  const encoded = encodeSigc(capture());
  assert.equal(Buffer.from(encoded).toString('hex'), pythonHex);
  const decoded = decodeSigc(fromHex(pythonHex));
  assert.deepEqual(decoded, capture());
});

test('scope export normalizes nanoseconds and rounds volts to millivolts', () => {
  const scope = new ScopeBuffer();
  scope.append(Float64Array.from([100, 0, 3.3, 110, 1, 2, 130, -0.25, 0]), 3, [0, 1]);
  assert.deepEqual(decodeSigc(scope.toSigc(['V', 'V'])), capture());
  const imported = new ScopeBuffer();
  imported.loadSigc(decodeSigc(scope.toSigc(['V', 'V'])));
  assert.equal(imported.length, 3);
  assert.equal(imported.lastTime(), 30);
  assert.equal(imported.v[0][imported.at(2)], -0.25);
  assert.throws(() => scope.toSigc(['V', 'A']), /SIGC stores millivolts only/);
});

test('SIGC import rejects malformed, oversize and unsupported captures', () => {
  const bytes = fromHex(pythonHex);
  assert.throws(() => decodeSigc(bytes.subarray(0, 50)), /Truncated SIGC/);
  const badVersion = bytes.slice(); badVersion[4] = 2;
  assert.throws(() => decodeSigc(badVersion), /Unsupported SIGC version/);
  const tooManyTraces = bytes.slice(); tooManyTraces[12] = 3;
  assert.throws(() => decodeSigc(tooManyTraces), /one or two voltage traces/);
  const badTime = bytes.slice(); badTime.fill(255, 36, 44);
  assert.throws(() => decodeSigc(badTime), (e: unknown) => e instanceof SigcError && /safe nanoseconds/.test(e.message));
});
